import{_ as i,l as n,o as e,c as l,v as t,p as s,x as r,d as o,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const G=JSON.parse('{"title":"Gamma Flip 零 gamma 位","description":"","frontmatter":{"title":"Gamma Flip 零 gamma 位","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gamma-flip-level.md","filePath":"quant/gamma-flip-level.md","lastUpdated":1789023840000}'),h={name:"quant/gamma-flip-level.md"};function d(g,a,S,f,c,u){const m=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="gamma-flip-零-gamma-位" tabindex="-1">Gamma Flip 零 gamma 位 <a class="header-anchor" href="#gamma-flip-零-gamma-位" aria-label="Permalink to &quot;Gamma Flip 零 gamma 位&quot;">​</a></h1><div class="epigraph"><p>净经销商 Gamma 作为现货的函数会穿过零；零点只是反馈符号的边界，不是由力学保证的吸铁石价位。</p><footer>—— 对冲反馈随净 Gamma 变号是 Black–Scholes 希腊字母的直接推论；公开链上零点是 GEX 口径下的数值根，识别条件同 Mixon / Gârleanu–Pedersen–Poteshman</footer></div><p>把 <a href="/quant/gex-calculation">GEX</a> 写成现货 \\(S\\) 的函数：每个执行价的 \\(\\Gamma(S;K,T,\\sigma)\\) 随标的移动而变，带符号的加总 \\(\\mathrm{GEX}(S)\\) 连续时会有根。从业者称这个根为 <strong>Gamma Flip</strong>（零 gamma 位）：\\(S\\) 在根之上与之下，经销商对冲的反馈符号相反。它在图上好看，也容易被讲成「价格会在 flip 处反弹」。公开文献只支持弱得多的命题：若净 Gamma 估计不太错，则跨越根时对冲需求的符号改变；<strong>根本身没有额外的吸引力</strong>，吸引力来自执行价附近的 Gamma 峰与 <a href="/quant/pin-risk">pin risk</a>，见 <a href="/quant/strike-magnetism-max-pain">Strike Magnetism</a>。本篇写如何解这个根、它随到期与 IV 怎么移，以及为什么不能把它当成支撑阻力。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定日终未平仓与微笑，\\(\\mathrm{GEX}(S)\\) 是一条可通过网格重估的曲线。在平值附近 Gamma 集中，曲线往往陡；在远离所有 \\(K\\) 处 Gamma 近零，曲线平坦。根可能有一个、多个或没有（整天同号）。问题是数值上的：用哪一个 \\(S\\) 网格、是否让每个 \\(K\\) 的 \\(\\sigma\\) 随 \\(S\\) 按 sticky strike 还是 sticky delta 移动。不同微笑动态给出不同的 \\(\\mathrm{GEX}(S)\\)，因而给出不同的 flip。这与 <a href="/quant/greeks-hedge">Delta 对冲</a> 里「用哪一个 Delta」是同一类模型选择，不是数据对错。</p><p>第二个问题是经济上的：即使根算对了，跨越它只改变<strong>边际</strong>对冲符号。若无符号 Gamma 存量很小，变号几乎没有流量含义。若存量很大但经销商并非残余持有人（符号约定错了），根在错误的曲线上。Mixon 的识别警告在零点上同样适用：公开 flip 是假设下的函数根。</p><h3 id="多根、平台与-0dte-尖峰" tabindex="-1">多根、平台与 0DTE 尖峰 <a class="header-anchor" href="#多根、平台与-0dte-尖峰" aria-label="Permalink to &quot;多根、平台与 0DTE 尖峰&quot;">​</a></h3><p>0DTE 把 Gamma 收成现货附近一根针，<a href="/quant/gex-calculation">GEX</a> 作为 \\(S\\) 的函数会在针的两侧迅速变号，根几乎贴着现货走——「flip 跟着价格」会让人误以为指标有预测力，其实是 \\(\\Gamma(S)\\) 的局部性。远月合约使曲线平滑、根稳定，但对当日对冲流贡献小。应报告 <strong>0DTE 根</strong> 与 <strong>剔除 0DTE 的根</strong> 两条，避免把针的几何当成体制。多根出现在多到期、多峰 OI 时：应列出全部根，或定义「距现货最近的根」，并承认选择规则是约定。</p><p><span class="marginnote">把 flip 画成水平线叠在 K 线图上，会暗示它是价格的函数之外的「位」。它其实是 \\(S\\) 的函数的根，现货一动、IV 一动、OI 一更新，根就移。静态水平线只是某次快照。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>网格重估。</strong> 在现货上下若干百分比取网格 \\(\\{S_j\\}\\)，每个 \\(S_j\\) 上重算全部合约的 \\(\\Gamma_{\\$}\\)（微笑规则预指定），用同一符号约定加总，得到 \\(\\mathrm{GEX}(S_j)\\)。在变号区间线性插值得根 \\(S^\\star\\)。精度到指数一点通常足够：对冲文献不支持把 flip 用到小数后两位去对交易。</p><p><strong>微笑规则。</strong> Sticky strike：每个 \\(K\\) 的 \\(\\sigma\\) 不变，\\(S\\) 移动只改变 \\(K/S\\)。Sticky delta：保持 Delta 的 \\(\\sigma\\) 不变，执行价的隐含波动随 \\(S\\) 平移。二者对虚值 Gamma 影响大于对平值，但仍会移动根。研究应预指定一种，并把另一种当稳健性，而不是挑使历史故事更好看的那种。</p><p><strong>时间。</strong> Charm 与日历流逝会在 OI 不变时改变 \\(\\Gamma\\)，因而移动 \\(S^\\star\\)，见 <a href="/quant/higher-greeks">Charm</a> 与 <a href="/quant/dealer-vanna-charm-flows">Vanna / Charm 流</a>。盘中只用日终 OI 重估 \\(S^\\star(S_t)\\)，是「仓位冻结、现货变动」的反事实，须在图注里写明。</p><h3 id="与最大痛点、最大-oi-执行价的区别" tabindex="-1">与最大痛点、最大 OI 执行价的区别 <a class="header-anchor" href="#与最大痛点、最大-oi-执行价的区别" aria-label="Permalink to &quot;与最大痛点、最大 OI 执行价的区别&quot;">​</a></h3><p>最大未平仓执行价、<a href="/quant/strike-magnetism-max-pain">最大痛点</a>、Gamma Flip 是三个不同的统计量。最大 OI 是仓位最厚的 \\(K\\)；最大痛点是使期权内在价值之和最小的交割价；flip 是净 Gamma 的零。它们可以碰巧接近（OI 厚的 \\(K\\) 附近 Gamma 也大），但没有恒等式。检验钉住应预指定看哪一个，Ni、Pearson 与 Poteshman（2005）用的是期权到期日的执行价聚类，不是 GEX 根。</p><p><span class="marginnote"> 根对符号约定一阶敏感：把看涨看跌的经销商符号对调，曲线翻号，根一般还在，但「之上为正还是为负」对调。体制叙事必须与 <a href="/quant/gex-calculation">GEX</a> 的同一约定绑定。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>在连续对冲的理想化里，经销商 Delta 对 \\(S\\) 的导数就是净 Gamma。\\(S\\) 穿过 \\(S^\\star\\) 时该导数变号，反馈从「逆趋势」换成「顺趋势」，或反过来。这是局部线性化的陈述，要求：对冲足够频繁、跳跃不大、存货符号正确。真实市场有离散对冲带、<a href="/quant/delta-hedge-freq">对冲频率</a> 与跳空，穿过 flip 的几分钟不必出现可识别的流量脉冲。公开研究能做的检验是：在日频或低频上，现货在 \\(S^\\star\\) 之上与之下，已实现波动或日内自相关是否不同——这是 <a href="/quant/dealer-gamma-regime">体制</a> 检验，不是「在 \\(S^\\star\\) 挂单」。</p><p>Flip 跟着 0DTE 现货走，说明当日凸性由当日合约主导；这时「位置相对 flip」几乎等于「位置相对平值」，信息增量有限。剔除短到期后的根，才更像存量体制的边界。</p><h3 id="为什么不是磁铁" tabindex="-1">为什么不是磁铁 <a class="header-anchor" href="#为什么不是磁铁" aria-label="Permalink to &quot;为什么不是磁铁&quot;">​</a></h3><p>磁铁需要恢复力：价格离开某点后被拉回。正 Gamma 体制提供的是<strong>阻尼</strong>（减波动），不是恢复到 \\(S^\\star\\)。负 Gamma 提供的是<strong>放大</strong>，更不是恢复。\\(S^\\star\\) 只是阻尼与放大的分界。把分界画成磁铁，是把体制边界误写成价格目标。执行价 \\(K\\) 上的钉住来自到期 Gamma 爆炸与行权阈值，对象是 \\(K\\) 不是 \\(S^\\star\\)。二者在图上接近时，叙事容易混，检验必须分开。</p>',21)),(e(),s(E,null,{default:r(()=>[p(m,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20OI%5B%22%E6%97%A5%E7%BB%88%20OI%20%E4%B8%8E%E5%BE%AE%E7%AC%91%E8%A7%84%E5%88%99%22%5D%20--%5Cgt%20%20CUR%5B%22GEX%20%E4%BD%9C%E4%B8%BA%20S%20%E7%9A%84%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20CUR%20--%5Cgt%20%20ROOT%5B%22%E5%8F%98%E5%8F%B7%E6%A0%B9%20S*%22%5D%0A%20%20ROOT%20--%5Cgt%20%20REG%5B%22S%20%E7%9B%B8%E5%AF%B9%20S*%20%E7%9A%84%E4%BD%93%E5%88%B6%E6%A0%87%E7%AD%BE%22%5D%0A%20%20REG%20--%5Cgt%20%20VOL%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%B3%A2%E5%8A%A8%20%2F%20%E6%97%A5%E5%86%85%E8%87%AA%E7%9B%B8%E5%85%B3%E6%A3%80%E9%AA%8C%22%5D%0A%20%20PIN%5B%22%E5%88%B0%E6%9C%9F%E6%89%A7%E8%A1%8C%E4%BB%B7%E9%92%89%E4%BD%8F%22%5D%20--%5Cgt%20%20DIFF%5B%22%E4%B8%8E%20S*%20%E5%88%86%E5%BC%80%E6%A3%80%E9%AA%8C%22%5D%0A%20%20ROOT%20--%5Cgt%20%20DIFF%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把 flip 当盘中支撑去交易：那超出公开识别，也把快照根当成固定位。不要在个股薄链上解根：OI 稀疏、IV 噪声会使 \\(\\mathrm{GEX}(S)\\) 乱跳。不要混用 SPX 与 SPY 的 \\(S\\) 而不换算。A 股没有同构的经销商 Gamma 披露，画「A 股 gamma flip」需要另一套持仓假设。</p><p>Flip 的正当用途是：<strong>与 GEX 同一口径的状态变量</strong>，用于样本外体制分层，并报告对微笑规则、符号约定、是否含 0DTE 的稳健性。它不提供执行算法。</p><p><span class="marginnote">新闻日微笑跳开，根可以瞬时移动数十点。事件日应把 flip 当不可靠，而不是当更精确的磁铁。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Gamma Flip 是带符号 GEX 作为现货函数的零点，依赖 OI、微笑动态与经销商符号约定。</li><li>0DTE 会使根贴着现货，增量信息少；应同时报告剔除短到期的根。</li><li>零点是对冲反馈的符号边界，不是价格磁铁；钉住属于执行价与 pin risk。</li><li>正当用法是体制分层与波动检验，不是把快照水平线当支撑阻力。</li><li>出处：希腊字母与对冲反馈为标准推论；识别同 Gârleanu, Pedersen and Poteshman, <em>RFS</em>, 2009 与 Mixon 对公开定位的讨论；到期钉住见 Ni, Pearson and Poteshman, <em>JFE</em>, 2005。</li></ul>',6))])}const A=i(h,[["render",d]]);export{G as __pageData,A as default};
